import { router, json, error, requireAuth, db, secrets, ai, storage } from '@appdeploy/sdk';

type Body = Record<string, unknown>;
type GeoPoint = { lat: number; lon: number; name: string };
type NearbyPlace = { name: string; lat: number; lon: number; kind: 'rail' | 'bus' | 'airport'; code?: string; address?: string };
async function photonTransportSearch(point: GeoPoint, kind: NearbyPlace['kind'], queryTerm: string): Promise<NearbyPlace[]> {
  try {
    const response = await fetch(`https://photon.komoot.io/api/?q=${encodeURIComponent(`${point.name} ${queryTerm}, India`)}&limit=8&lang=en`, { headers: { 'User-Agent': 'GoldenPerfectTravel/1.0' } });
    if (!response.ok) return [];
    const data = await response.json() as { features?: Array<{ geometry?: { coordinates?: number[] }; properties?: { name?: string; city?: string; state?: string; postcode?: string } }> };
    return (data.features || []).map((feature) => {
      const coordinates = feature.geometry?.coordinates;
      const props = feature.properties || {};
      return { name: props.name || queryTerm, lat: Number(coordinates?.[1]), lon: Number(coordinates?.[0]), kind, address: [props.city, props.state, props.postcode].filter(Boolean).join(', ') };
    }).filter((item) => Number.isFinite(item.lat) && Number.isFinite(item.lon))
      .sort((a, b) => distanceScore(point.lat, point.lon, a.lat, a.lon) - distanceScore(point.lat, point.lon, b.lat, b.lon))
      .filter((item, index, all) => all.findIndex((candidate) => `${candidate.kind}:${candidate.name}` === `${item.kind}:${item.name}`) === index)
      .slice(0, 8);
  } catch { return []; }
}
const TRAIN_SNAPSHOT_URL = 'https://raw.githubusercontent.com/datameet/railways/master/trains.json';
let trainSnapshotPromise: Promise<unknown[]> | null = null;
function distanceScore(aLat: number, aLon: number, bLat: number, bLon: number) { const lat = (aLat - bLat) * 111; const lon = (aLon - bLon) * 111 * Math.cos((aLat * Math.PI) / 180); return Math.sqrt(lat * lat + lon * lon); }
async function geocodePhoton(query: string): Promise<GeoPoint | null> { try { const response = await fetch(`https://photon.komoot.io/api/?q=${encodeURIComponent(`${query}, India`)}&limit=1&lang=en`, { headers: { 'User-Agent': 'GoldenPerfectTravel/1.0' } }); if (!response.ok) return null; const data = await response.json() as { features?: Array<{ geometry?: { coordinates?: number[] }; properties?: { name?: string; city?: string; state?: string } }> }; const feature = data.features?.[0]; const coordinates = feature?.geometry?.coordinates; if (!coordinates || coordinates.length < 2) return null; return { lat: Number(coordinates[1]), lon: Number(coordinates[0]), name: [feature.properties?.name, feature.properties?.city, feature.properties?.state].filter(Boolean).join(', ') || query }; } catch { return null; } }
async function nearbyTransport(point: GeoPoint): Promise<NearbyPlace[]> { const query = `[out:json][timeout:20];(nwr[railway~"station|halt"](around:18000,${point.lat},${point.lon});nwr[amenity="bus_station"](around:18000,${point.lat},${point.lon});nwr[public_transport="station"][bus=yes](around:18000,${point.lat},${point.lon});nwr[aeroway="aerodrome"](around:40000,${point.lat},${point.lon}););out center tags;`; try { const response = await fetch('https://overpass-api.de/api/interpreter', { method: 'POST', headers: { 'Content-Type': 'text/plain', 'User-Agent': 'GoldenPerfectTravel/1.0' }, body: query }); if (!response.ok) return []; const data = await response.json() as { elements?: Array<{ lat?: number; lon?: number; center?: { lat: number; lon: number }; tags?: Record<string, string> }> }; return (data.elements || []).map((item) => { const lat = Number(item.lat ?? item.center?.lat); const lon = Number(item.lon ?? item.center?.lon); const tags = item.tags || {}; const kind: NearbyPlace['kind'] = tags.aeroway === 'aerodrome' ? 'airport' : tags.railway ? 'rail' : 'bus'; return { name: tags.name || tags['name:en'] || (kind === 'rail' ? 'Railway station' : kind === 'bus' ? 'Bus station' : 'Airport'), lat, lon, kind, code: tags['railway:ref'] || tags.ref || tags.iata, address: tags['addr:city'] || tags['addr:street'] }; }).filter((item) => Number.isFinite(item.lat) && Number.isFinite(item.lon)).sort((a, b) => distanceScore(point.lat, point.lon, a.lat, a.lon) - distanceScore(point.lat, point.lon, b.lat, b.lon)).filter((item, index, all) => all.findIndex((candidate) => `${candidate.kind}:${candidate.name}` === `${item.kind}:${item.name}`) === index).slice(0, 10); } catch { return []; } }
async function loadTrainSnapshot() { if (!trainSnapshotPromise) trainSnapshotPromise = fetch(TRAIN_SNAPSHOT_URL, { headers: { 'User-Agent': 'GoldenPerfectTravel/1.0' } }).then(async (response) => response.ok ? await response.json() as unknown[] : []).catch(() => []); return trainSnapshotPromise; }
async function findTrainReferences(origin: GeoPoint, destination: GeoPoint) { const raw = await loadTrainSnapshot(); return raw.flatMap((item) => { const feature = item as { geometry?: { coordinates?: number[][] }; properties?: Record<string, unknown> }; const coordinates = feature.geometry?.coordinates; const properties = feature.properties; if (!coordinates?.length || !properties) return []; const first = coordinates[0]; const last = coordinates[coordinates.length - 1]; if (!first || !last || first.length < 2 || last.length < 2) return []; const direct = distanceScore(origin.lat, origin.lon, Number(first[1]), Number(first[0])) + distanceScore(destination.lat, destination.lon, Number(last[1]), Number(last[0])); const reverse = distanceScore(origin.lat, origin.lon, Number(last[1]), Number(last[0])) + distanceScore(destination.lat, destination.lon, Number(first[1]), Number(first[0])); if (Math.min(direct, reverse) > 180) return []; return [{ number: String(properties.number || ''), name: String(properties.name || ''), type: String(properties.type || 'Train'), from: String(properties.from_station_name || ''), to: String(properties.to_station_name || ''), score: Math.min(direct, reverse) }]; }).filter((item) => item.number && item.name).sort((a, b) => a.score - b.score).slice(0, 8); }
async function fetchPageText(url: string) { try { const response = await fetch(url, { headers: { 'User-Agent': 'GoldenPerfectTravel/1.0' } }); if (!response.ok) return ''; const html = await response.text(); return html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').slice(0, 24000); } catch { return ''; } }
async function buildAiRouteAnswer(from: string, to: string, date: string, context: unknown) { const fromSlug = encodeURIComponent(from.trim().toLowerCase().replace(/\\s+/g, '-')); const toSlug = encodeURIComponent(to.trim().toLowerCase().replace(/\\s+/g, '-')); const urls = [`https://www.ixigo.com/by-train-rail/${fromSlug}-to-${toSlug}-by-train`, `https://www.redbus.in/bus-tickets/${fromSlug}-to-${toSlug}`, `https://www.makemytrip.com/bus-tickets/${fromSlug}-${toSlug}_bus-ticket-booking.html`, `https://www.google.com/travel/flights?q=${encodeURIComponent(`Flights from ${from} to ${to}${date ? ` on ${date}` : ''}`)}`]; const pages = await Promise.all(urls.map(fetchPageText)); const sourceBundle = pages.map((text, index) => `SOURCE ${index + 1}: ${urls[index]}\\n${text}`).join('\\n\\n'); const result = await ai.run({ system: 'You are the live travel-planning engine for an India travel app. Give practical, route-specific answers. Use only facts supported by the supplied map/timetable/provider source text or clearly label an item as needing live verification. Never invent train numbers, bus operators, flight numbers, prices, timings, stations, airports, seats or availability. If direct service is not supported, explain a sensible connection using only supported locations/services; otherwise say that a connection must be checked live. Prefer exact names, numbers, prices, timings, boarding points and arrival points when present. Include a short map/search instruction using the supplied real locations. Mention that prices and availability can change by date.', prompt: `Plan ${from} to ${to}${date ? ` for ${date}` : ''}. Return a concise but useful answer with sections: BEST DIRECT OPTIONS, IF NO DIRECT SERVICE, TRAIN, BUS, FLIGHT, BOARDING/ARRIVAL LOCATIONS, PRICE & TIME, and VERIFICATION. Context: ${JSON.stringify(context)}\\nProvider source text: ${sourceBundle}`, maxSteps: 4, maxTokens: 1800, thinkingMode: 'FAST' }); return result.text; }
async function buildTravelRecommendation(body: Body) { const from = String(body.from || '').trim(); const to = String(body.to || '').trim(); const date = String(body.date || '').trim(); if (!from || !to) return null; const [origin, destination] = await Promise.all([geocodePhoton(from), geocodePhoton(to)]); if (!origin || !destination) return { found: false, message: 'Could not locate the origin or destination. Try a city name, railway station, airport or district.' }; const [originTransportRaw, destinationTransportRaw, trains] = await Promise.all([nearbyTransport(origin), nearbyTransport(destination), findTrainReferences(origin, destination)]);
  const originTransport = originTransportRaw.length ? originTransportRaw : (await Promise.all([photonTransportSearch(origin, 'rail', 'railway station'), photonTransportSearch(origin, 'bus', 'bus station'), photonTransportSearch(origin, 'airport', 'airport')])).flat();
  const destinationTransport = destinationTransportRaw.length ? destinationTransportRaw : (await Promise.all([photonTransportSearch(destination, 'rail', 'railway station'), photonTransportSearch(destination, 'bus', 'bus station'), photonTransportSearch(destination, 'airport', 'airport')])).flat(); const mapped = { origin: { rail: originTransport.filter((x) => x.kind === 'rail').slice(0, 5), bus: originTransport.filter((x) => x.kind === 'bus').slice(0, 5), airport: originTransport.filter((x) => x.kind === 'airport').slice(0, 4) }, destination: { rail: destinationTransport.filter((x) => x.kind === 'rail').slice(0, 5), bus: destinationTransport.filter((x) => x.kind === 'bus').slice(0, 5), airport: destinationTransport.filter((x) => x.kind === 'airport').slice(0, 4) } }; let aiAnswer = ''; try { aiAnswer = await buildAiRouteAnswer(from, to, date, { resolvedOrigin: origin, resolvedDestination: destination, trains, mapped }); } catch (err) { console.warn('AI route answer unavailable', err); } return { found: true, origin: { ...origin, railStations: mapped.origin.rail, busStops: mapped.origin.bus, airports: mapped.origin.airport }, destination: { ...destination, railStations: mapped.destination.rail, busStops: mapped.destination.bus, airports: mapped.destination.airport }, trains, trainData: trains.length ? 'reference_snapshot' : 'not_found', trainDataNote: 'Train names shown from a public timetable snapshot. Verify running day, platform, live status and fare on an official/current railway service before booking.', officialTrainSearchUrl: 'https://www.indianrail.gov.in/enquiry/SEAT/SeatAvailability.html?locale=en', aiAnswer, generatedAt: new Date().toISOString(), mapAttribution: 'Transport locations from OpenStreetMap contributors.' }; }

async function nextBookingNumber() {
  const result = await db.list<{ value?: number }>('booking_sequences', { limit: 1 });
  if (!result.items[0]) {
    const [id] = await db.add('booking_sequences', [{ value: 1 }]);
    if (!id) throw new Error('Could not initialize booking number sequence');
    return 1;
  }
  const current = result.items[0];
  const next = Math.max(1, Number(current.value || 0) + 1);
  const ok = await db.update('booking_sequences', [{ id: current.id, record: { value: next } }]);
  if (!ok[0]) throw new Error('Could not update booking number sequence');
  return next;
}


async function ledgerList() { return (await db.list<Record<string, unknown>>('revenue_ledger', { limit: 500 })).items; }
function validLedgerSource(value: unknown) { return ['adsense', 'direct', 'partnership', 'booking', 'other'].includes(String(value)); }
function validLedgerStatus(value: unknown) { return ['estimated', 'confirmed', 'paid'].includes(String(value)); }
function validAmount(value: unknown, allowZero = false) { const amount = Number(value); return Number.isFinite(amount) && (allowZero ? amount >= 0 : amount > 0) && amount <= 100000000000; }
async function addLedgerEntry(ctx: Parameters<ReturnType<typeof router>>[0], input: Body) {
  const source = String(input.source || 'other');
  const amount = Number(input.amount);
  const date = String(input.date || new Date().toISOString().slice(0, 10)).slice(0, 10);
  const status = String(input.status || 'confirmed');
  if (!validLedgerSource(source) || !validLedgerStatus(status) || !validAmount(amount, true) || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return { error: error('Valid source, status, date and non-negative amount are required.', 400) };
  const now = new Date().toISOString();
  const record = { date, source, campaignId: String(input.campaignId || ''), partnerId: String(input.partnerId || ''), placement: String(input.placement || ''), amount, status, note: String(input.note || '').trim(), createdBy: ctx.user!.email || ADMIN_EMAIL, createdAt: now, updatedAt: now };
  const [id] = await db.add('revenue_ledger', [record]);
  if (!id) return { error: error('Could not save revenue ledger entry.', 500) };
  return { record: { id, ...record } };
}
async function syncCampaignEstimates() {
  const [campaignPage, ledgerPage] = await Promise.all([db.list<Record<string, unknown>>('ad_campaigns', { limit: 200 }), ledgerList()]);
  const today = new Date().toISOString().slice(0, 10);
  for (const campaign of campaignPage.items) {
    const id = String(campaign.id);
    const budget = Math.max(0, Number(campaign.budget || 0));
    const rate = Math.max(0, Number(campaign.rate || 0));
    const pricingModel = String(campaign.pricingModel || 'flat');
    const start = String(campaign.startDate || today).slice(0, 10);
    const end = String(campaign.endDate || start).slice(0, 10);
    const eligible = start <= today && end >= today;
    const dailyEntries = ledgerPage.filter(row => row.source === 'direct' && row.status === 'estimated' && String(row.campaignId || '') === id);
    const confirmedSpend = ledgerPage.filter(row => row.source === 'direct' && row.status !== 'estimated' && String(row.campaignId || '') === id).reduce((sum, row) => sum + Number(row.amount || 0), 0);
    const impressions = Math.max(0, Number(campaign.impressions || 0));
    const clicks = Math.max(0, Number(campaign.clicks || 0));
    const rawEstimate = pricingModel === 'cpm' ? impressions / 1000 * rate : pricingModel === 'cpc' ? clicks * rate : eligible ? rate / Math.max(1, Math.round((Date.parse(end) - Date.parse(start)) / 86400000) + 1) : 0;
    const remaining = Math.max(0, budget > 0 ? budget - confirmedSpend : Number.POSITIVE_INFINITY);
    const estimate = Math.max(0, Math.min(Number.isFinite(rawEstimate) ? rawEstimate : 0, remaining));
    const todayEntry = dailyEntries.find(row => String(row.date || '').slice(0, 10) === today);
    if (todayEntry) {
      const current = await db.get<Record<string, unknown>>('revenue_ledger', [String(todayEntry.id)]);
      if (current[0]) await db.update('revenue_ledger', [{ id: String(todayEntry.id), record: { ...current[0], amount: estimate, updatedAt: new Date().toISOString(), note: 'Auto-calculated campaign estimate; refreshed from campaign stats.' } }]);
    } else if (eligible && estimate > 0) {
      await db.add('revenue_ledger', [{ date: today, source: 'direct', campaignId: id, partnerId: '', placement: String(campaign.placement || ''), amount: estimate, status: 'estimated', note: 'Auto-calculated campaign estimate.', createdBy: 'campaign-estimator', createdAt: new Date().toISOString() }]);
    }
    const spentEstimate = ledgerPage.filter(row => String(row.campaignId || '') === id && row.status === 'estimated').reduce((sum, row) => sum + Number(row.amount || 0), 0);
    const spentConfirmed = confirmedSpend + spentEstimate;
    if (budget > 0 && spentConfirmed >= budget && String(campaign.status || '') !== 'Paused') {
      await db.update('ad_campaigns', [{ id, record: { ...campaign, status: 'Paused', pausedReason: 'Campaign budget reached', updatedAt: new Date().toISOString() } }]);
    }
  }
}
export async function revenueEstimateCron() {
  try { await syncCampaignEstimates(); } catch (err) { console.error('Revenue estimate cron failed', err); }
  return { statusCode: 200 };
}

const ADMIN_EMAIL = 'abgupta802215@gmail.com';

function isAdminIdentity(ctx: Parameters<ReturnType<typeof router>>[0]) {
  return Boolean(ctx.user?.userId && String(ctx.user.email || '').trim().toLowerCase() === ADMIN_EMAIL);
}

async function requireAdminSession(ctx: Parameters<ReturnType<typeof router>>[0]) {
  if (!isAdminIdentity(ctx)) return error('Admin access is restricted to the authorized account', 403);
  return null;
}

async function blockedUser(userId: string) {
  const result = await db.list<Record<string, unknown>>('blocked_users', { limit: 1, filter: { userId, blocked: true } });
  return Boolean(result.items[0]);
}

async function requireUnblocked(ctx: Parameters<ReturnType<typeof router>>[0]) {
  if (await blockedUser(ctx.user!.userId)) return error('This account is blocked from creating or changing travel data. Contact Golden Perfect support.', 403);
  return null;
}

type NotesPlaceRecord = { userId: string; name: string; location: string; imagePath?: string; imageUrl?: string; favorite: boolean; createdAt: string; updatedAt: string };
type NotesRecord = { userId: string; placeId: string; day: number; date: string; time: string; title: string; text: string; location: string; tag: string; favorite: boolean; checklist: Array<{ text: string; done: boolean }>; expenseLabel: string; expenseAmount: number; photoPath?: string; photoUrl?: string; createdAt: string; updatedAt: string };

async function listUserPlaces(userId: string) { const items: Array<NotesPlaceRecord & { id: string }> = []; let nextToken: string | undefined; for (let page = 0; page < 10; page += 1) { const result = await db.list<NotesPlaceRecord>('travel_note_places', { limit: 50, nextToken, filter: { userId } }); items.push(...result.items); if (!result.nextToken) break; nextToken = result.nextToken; } return { items }; }
async function listUserNotes(userId: string) { const items: Array<NotesRecord & { id: string }> = []; let nextToken: string | undefined; for (let page = 0; page < 10; page += 1) { const result = await db.list<NotesRecord>('travel_notes', { limit: 100, nextToken, filter: { userId } }); items.push(...result.items); if (!result.nextToken) break; nextToken = result.nextToken; } return { items }; }
async function withSignedUrls<T extends { imagePath?: string; photoPath?: string }>(items: Array<T>) {
  const paths = items.flatMap((item) => [item.imagePath, item.photoPath]).filter((path): path is string => Boolean(path));
  if (!paths.length) return items;
  const unique = Array.from(new Set(paths));
  const urls = await storage.url(unique);
  const map = new Map(urls.map((item) => [item.path, item.url]));
  return items.map((item) => ({ ...item, imageUrl: item.imagePath ? map.get(item.imagePath) : undefined, photoUrl: item.photoPath ? map.get(item.photoPath) : undefined }));
}
async function deleteStoredPaths(paths: Array<string | undefined>) { const clean = paths.filter((path): path is string => Boolean(path)); if (clean.length) await storage.delete(Array.from(new Set(clean))); }

